// Generated by AI (UnitTest MCP)
//! Deterministic Rust module-graph extraction.
//!
//! Rust files declare their neighbours precisely — `mod foo;` names a file, and
//! `use crate::a::b` names a module path — so the edges between them can be
//! recovered without compiling anything and without spending a token.
//!
//! Resolution is candidate-based, exactly as the JavaScript arm is: a `use`
//! path cannot be split into "module part" and "item part" by looking at it
//! (`crate::graph::GraphStore` and `crate::graph::query` are the same shape),
//! so every prefix is offered longest-first and the store picks the one it
//! already knows. Guessing is left to the caller that holds the file list.

use super::{Import, ImportBinding, ImportTarget};
use crate::ingest::normalize_path;
use regex::Regex;
use std::sync::OnceLock;

/// Roots that resolve to the toolchain rather than to a file in this workspace.
const TOOLCHAIN_ROOTS: [&str; 3] = ["std", "core", "alloc"];

fn supports_rust(path: &str) -> bool {
    path.rsplit('.')
        .next()
        .unwrap_or("")
        .eq_ignore_ascii_case("rs")
}

/// Where a file's child, sibling, and crate-root modules live on disk.
///
/// Rust puts a module's children in a directory named after it, except for the
/// three roots (`lib.rs`, `main.rs`, `mod.rs`) which own the directory they sit
/// in. Getting this wrong silently resolves every `mod` in the file to the
/// wrong directory, so it is computed once and shared.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ModuleLayout {
    /// Directory holding this module's children (`self::`, `mod x;`).
    module_dir: String,
    /// Directory holding this module's siblings (`super::`).
    parent_dir: String,
    /// Directory holding the crate root (`crate::`).
    crate_dir: String,
    /// Whether this file is itself a module root (`lib.rs`/`main.rs`/`mod.rs`).
    is_root_file: bool,
}

impl ModuleLayout {
    fn for_path(path: &str) -> Option<ModuleLayout> {
        let norm = normalize_path(path);
        let (dir, file) = match norm.rsplit_once('/') {
            Some((dir, file)) => (format!("{dir}/"), file.to_string()),
            None => (String::new(), norm.clone()),
        };
        let stem = file.strip_suffix(".rs")?;

        // The crate root is the nearest enclosing `src/`. Without one (a build
        // script, an example laid out flat) the file's own directory is the
        // best deterministic answer, and is still correct for `self`/`super`.
        let crate_dir = match dir.rfind("src/") {
            Some(at) => dir[..at + "src/".len()].to_string(),
            None => dir.clone(),
        };

        let is_root_file = matches!(stem, "lib" | "main" | "mod");
        let (module_dir, parent_dir) = if is_root_file {
            (dir.clone(), parent_of(&dir))
        } else {
            (format!("{dir}{stem}/"), dir.clone())
        };

        Some(ModuleLayout {
            module_dir,
            parent_dir,
            crate_dir,
            is_root_file,
        })
    }
}

/// Strip one trailing path segment: `a/b/c/` -> `a/b/`.
fn parent_of(dir: &str) -> String {
    let trimmed = dir.trim_end_matches('/');
    match trimmed.rsplit_once('/') {
        Some((head, _)) => format!("{head}/"),
        None => String::new(),
    }
}

/// Extract the module edges a Rust file declares, without executing anything.
pub fn extract(path: &str, content: &str) -> Vec<Import> {
    if !supports_rust(path) {
        return Vec::new();
    }
    let Some(layout) = ModuleLayout::for_path(path) else {
        return Vec::new();
    };
    // Comments are masked rather than removed so byte offsets stay meaningful
    // and a `use` quoted inside a doc comment cannot be mistaken for a real one.
    let code = mask_comments_and_strings(content);

    let mut imports: Vec<Import> = Vec::new();
    for capture in mod_declaration().captures_iter(&code) {
        let name = capture[1].to_string();
        // `mod x;` is a file; `mod x { .. }` is not, and the regex requires the
        // semicolon precisely so an inline test module never invents a path.
        let candidates = vec![
            format!("{}{name}.rs", layout.module_dir),
            format!("{}{name}/mod.rs", layout.module_dir),
        ];
        merge(
            &mut imports,
            Import {
                specifier: format!("mod {name}"),
                target: ImportTarget::ArtifactCandidates(candidates),
                bindings: Vec::new(),
            },
        );
    }

    for capture in use_declaration().captures_iter(&code) {
        for import in resolve_use(&layout, &capture[1]) {
            merge(&mut imports, import);
        }
    }
    imports
}

fn mod_declaration() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(r"(?m)^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?mod[ \t]+([A-Za-z_]\w*)[ \t]*;").expect(
            "mod-declaration pattern is a compile-time constant and is covered by unit tests",
        )
    })
}

fn use_declaration() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        // `(?s)` because a grouped `use` spans lines; non-greedy to the first
        // `;`, which is unambiguous because a use-tree contains none.
        Regex::new(r"(?ms)^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?use[ \t]+(.+?);").expect(
            "use-declaration pattern is a compile-time constant and is covered by unit tests",
        )
    })
}

/// Turn one use-tree into imports, or no imports when it names the toolchain.
fn resolve_use(layout: &ModuleLayout, tree: &str) -> Vec<Import> {
    let tree = tree.trim();
    let (head, group) = match tree.find('{') {
        Some(at) => (
            &tree[..at],
            Some(tree[at + 1..].trim_end().trim_end_matches('}')),
        ),
        None => (tree, None),
    };

    let mut segments: Vec<String> = head
        .split("::")
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .map(str::to_string)
        .collect();
    if segments.is_empty() && group.is_none() {
        return Vec::new();
    }

    let Some(root) = segments.first().cloned() else {
        return Vec::new();
    };
    if TOOLCHAIN_ROOTS.contains(&root.as_str()) {
        return Vec::new();
    }

    let mut external_crate = None;
    let base = match root.as_str() {
        "crate" => {
            segments.remove(0);
            layout.crate_dir.clone()
        }
        "self" => {
            segments.remove(0);
            layout.module_dir.clone()
        }
        "super" => {
            let mut dir = layout.parent_dir.clone();
            segments.remove(0);
            // `super::super::x` walks up once more per extra `super`.
            while segments.first().map(String::as_str) == Some("super") {
                segments.remove(0);
                dir = parent_of(&dir);
            }
            dir
        }
        _ => {
            segments.remove(0);
            external_crate = Some(root);
            String::new()
        }
    };

    let branches = match group {
        Some(items) => grouped_branches(&segments, items),
        None => vec![simple_branch(segments)],
    };
    let mut imports = Vec::new();
    for branch in branches {
        let target = match &external_crate {
            Some(name) => ImportTarget::RustCrate {
                name: name.clone(),
                segments: branch.modules,
            },
            None => {
                let candidates = module_candidates(layout, &base, &branch.modules);
                if candidates.is_empty() {
                    continue;
                }
                ImportTarget::ArtifactCandidates(candidates)
            }
        };
        merge(
            &mut imports,
            Import {
                specifier: tree.to_string(),
                target,
                bindings: branch.bindings,
            },
        );
    }
    imports
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct UseBranch {
    modules: Vec<String>,
    bindings: Vec<ImportBinding>,
}

fn simple_branch(mut segments: Vec<String>) -> UseBranch {
    let mut bindings = Vec::new();
    if let Some(last) = segments.last_mut() {
        let (imported, local) = aliased_name(last);
        if is_item_name(&imported) {
            *last = imported.clone();
            bindings.push(ImportBinding { imported, local });
        }
    }
    UseBranch {
        modules: segments,
        bindings,
    }
}

fn grouped_branches(prefix: &[String], items: &str) -> Vec<UseBranch> {
    let mut branches = Vec::new();
    for item in split_group(items) {
        expand_group_item(prefix, item, &mut branches);
    }
    branches
}

fn expand_group_item(prefix: &[String], raw: &str, branches: &mut Vec<UseBranch>) {
    let item = raw.trim();
    if item.is_empty() {
        return;
    }
    if let Some(open) = item.find('{') {
        let mut nested_prefix = prefix.to_vec();
        nested_prefix.extend(path_segments(&item[..open]));
        let nested = item[open + 1..].trim_end().trim_end_matches('}');
        for child in split_group(nested) {
            expand_group_item(&nested_prefix, child, branches);
        }
        return;
    }

    let mut path = path_segments(item);
    let Some(last) = path.pop() else {
        return;
    };
    let (imported, local) = aliased_name(&last);
    let mut modules = prefix.to_vec();
    modules.extend(path);
    let bindings = if is_item_name(&imported) {
        vec![ImportBinding { imported, local }]
    } else {
        Vec::new()
    };
    if let Some(existing) = branches.iter_mut().find(|branch| branch.modules == modules) {
        for binding in bindings {
            if !existing.bindings.contains(&binding) {
                existing.bindings.push(binding);
            }
        }
    } else {
        branches.push(UseBranch { modules, bindings });
    }
}

fn split_group(items: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (index, ch) in items.char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => depth = depth.saturating_sub(1),
            ',' if depth == 0 => {
                out.push(&items[start..index]);
                start = index + ch.len_utf8();
            }
            _ => {}
        }
    }
    out.push(&items[start..]);
    out
}

fn path_segments(path: &str) -> Vec<String> {
    path.trim()
        .trim_end_matches("::")
        .split("::")
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .map(str::to_string)
        .collect()
}

fn aliased_name(item: &str) -> (String, String) {
    let mut parts = item.splitn(2, " as ");
    let imported = parts.next().unwrap_or(item).trim().to_string();
    let local = parts.next().unwrap_or(&imported).trim().to_string();
    (imported, local)
}

/// Candidate files for a module path, most specific first.
///
/// `crate::graph::query` may be `graph/query.rs`, `graph/query/mod.rs`, or an
/// item named `query` inside `graph.rs`. All are offered; the store keeps
/// whichever it has already seen.
fn module_candidates(layout: &ModuleLayout, base: &str, segments: &[String]) -> Vec<String> {
    let mut out = Vec::new();
    for len in (1..=segments.len()).rev() {
        let joined = segments[..len].join("/");
        out.push(format!("{base}{joined}.rs"));
        out.push(format!("{base}{joined}/mod.rs"));
    }
    // The item may live in the base module itself (`use crate::{Thing}`).
    if base == layout.crate_dir {
        out.push(format!("{base}lib.rs"));
        out.push(format!("{base}main.rs"));
    }
    out.push(format!("{base}mod.rs"));
    out.dedup();
    out
}

fn is_item_name(name: &str) -> bool {
    !name.is_empty()
        && name != "self"
        && name != "*"
        && name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
}

/// Blank out comments and string literals so their contents never parse as code.
fn mask_comments_and_strings(content: &str) -> String {
    let bytes = content.as_bytes();
    let mut out = String::with_capacity(content.len());
    let mut index = 0usize;
    let mut block_depth = 0usize;
    while index < bytes.len() {
        let ch = bytes[index] as char;
        if block_depth > 0 {
            if bytes[index..].starts_with(b"/*") {
                block_depth += 1;
                out.push_str("  ");
                index += 2;
                continue;
            }
            if bytes[index..].starts_with(b"*/") {
                block_depth -= 1;
                out.push_str("  ");
                index += 2;
                continue;
            }
            out.push(if ch == '\n' { '\n' } else { ' ' });
            index += 1;
            continue;
        }
        if bytes[index..].starts_with(b"/*") {
            block_depth = 1;
            out.push_str("  ");
            index += 2;
            continue;
        }
        if bytes[index..].starts_with(b"//") {
            while index < bytes.len() && bytes[index] != b'\n' {
                out.push(' ');
                index += 1;
            }
            continue;
        }
        if ch == '"' {
            out.push(' ');
            index += 1;
            while index < bytes.len() {
                if bytes[index] == b'\\' {
                    out.push_str("  ");
                    index += 2;
                    continue;
                }
                if bytes[index] == b'"' {
                    out.push(' ');
                    index += 1;
                    break;
                }
                out.push(if bytes[index] == b'\n' { '\n' } else { ' ' });
                index += 1;
            }
            continue;
        }
        out.push(ch);
        index += ch.len_utf8();
    }
    out
}

/// Keep one import per target, unioning bindings.
fn merge(imports: &mut Vec<Import>, incoming: Import) {
    if let Some(existing) = imports
        .iter_mut()
        .find(|import| import.target == incoming.target)
    {
        for binding in incoming.bindings {
            if !existing.bindings.contains(&binding) {
                existing.bindings.push(binding);
            }
        }
        return;
    }
    imports.push(incoming);
}

#[cfg(test)]
mod tests {
    use super::*;

    fn candidates(imports: &[Import], specifier_contains: &str) -> Vec<String> {
        imports
            .iter()
            .find(|import| import.specifier.contains(specifier_contains))
            .map(|import| match &import.target {
                ImportTarget::ArtifactCandidates(list) => list.clone(),
                ImportTarget::RustCrate { name, .. } => vec![format!("crate:{name}")],
                ImportTarget::Package(name) => vec![format!("package:{name}")],
            })
            .unwrap_or_default()
    }

    #[test]
    fn a_non_rust_file_is_not_ours() {
        assert!(extract("src/app.ts", "import x from './y';").is_empty());
    }

    #[test]
    fn mod_declaration_names_a_sibling_file_or_its_directory() {
        let found = extract("crates/c/src/graph/mod.rs", "pub mod query;\nmod writes;\n");
        assert_eq!(
            candidates(&found, "mod query"),
            vec![
                "crates/c/src/graph/query.rs".to_string(),
                "crates/c/src/graph/query/mod.rs".to_string(),
            ]
        );
        assert_eq!(
            candidates(&found, "mod writes"),
            vec![
                "crates/c/src/graph/writes.rs".to_string(),
                "crates/c/src/graph/writes/mod.rs".to_string(),
            ]
        );
    }

    #[test]
    fn a_non_root_file_owns_a_directory_named_after_it() {
        // `graph.rs` declares `mod query;`, whose file is `graph/query.rs` —
        // not `query.rs` beside it. Resolving this against the file's own
        // directory would point every child module at the wrong place.
        let found = extract("crates/c/src/graph.rs", "mod query;\n");
        assert_eq!(
            candidates(&found, "mod query"),
            vec![
                "crates/c/src/graph/query.rs".to_string(),
                "crates/c/src/graph/query/mod.rs".to_string(),
            ]
        );
    }

    #[test]
    fn an_inline_mod_block_is_not_a_file() {
        // `#[cfg(test)] mod tests { .. }` has no file behind it. Emitting one
        // would invent an artifact node for a path that cannot exist.
        let found = extract(
            "crates/c/src/graph.rs",
            "#[cfg(test)]\nmod tests {\n    fn t() {}\n}\n",
        );
        assert!(
            found.is_empty(),
            "an inline module declares no file; got {found:?}"
        );
    }

    #[test]
    fn a_crate_path_resolves_from_the_nearest_src_root() {
        let found = extract(
            "crates/c/src/facade/query.rs",
            "use crate::graph::query::Thing;\n",
        );
        let list = candidates(&found, "crate::graph::query");
        assert_eq!(
            list.first(),
            Some(&"crates/c/src/graph/query/Thing.rs".to_string()),
            "most specific candidate first; got {list:?}"
        );
        assert!(
            list.contains(&"crates/c/src/graph/query.rs".to_string()),
            "the module that actually holds the item must be offered; got {list:?}"
        );
        assert!(
            list.contains(&"crates/c/src/graph.rs".to_string()),
            "a shorter prefix must be offered too; got {list:?}"
        );
    }

    #[test]
    fn super_walks_up_one_directory_per_super() {
        let found = extract(
            "crates/c/src/graph/query/traversal.rs",
            "use super::super::types::Node;\n",
        );
        let list = candidates(&found, "super::super::types");
        assert!(
            list.contains(&"crates/c/src/graph/types.rs".to_string()),
            "two supers from graph/query/traversal.rs reach graph/; got {list:?}"
        );
    }

    #[test]
    fn a_grouped_use_binds_every_leaf() {
        let found = extract(
            "crates/c/src/lib.rs",
            "use crate::graph::{Edge, Node as Vertex, ScoredNode};\n",
        );
        let import = found
            .iter()
            .find(|import| import.specifier.contains("crate::graph"))
            .expect("the grouped use is extracted");
        let names: Vec<&str> = import
            .bindings
            .iter()
            .map(|binding| binding.imported.as_str())
            .collect();
        assert_eq!(names, vec!["Edge", "Node", "ScoredNode"]);
        assert_eq!(import.bindings[1].local, "Vertex");
    }

    #[test]
    fn a_nested_grouped_use_resolves_every_module_branch() {
        // Bug regression: the outer group parser treated `b::{C, D}` as one
        // invalid leaf, so `a/b.rs` never received an import edge and impact
        // traversal silently omitted its dependents.
        let found = extract(
            "crates/c/src/lib.rs",
            "use crate::a::{b::{C, D as Renamed}, E};\n",
        );

        let nested = found
            .iter()
            .find(|import| match &import.target {
                ImportTarget::ArtifactCandidates(paths) => {
                    paths.contains(&"crates/c/src/a/b.rs".to_string())
                }
                ImportTarget::RustCrate { .. } | ImportTarget::Package(_) => false,
            })
            .expect("the nested b branch is extracted");
        assert_eq!(
            nested.bindings,
            vec![
                ImportBinding {
                    imported: "C".to_string(),
                    local: "C".to_string(),
                },
                ImportBinding {
                    imported: "D".to_string(),
                    local: "Renamed".to_string(),
                },
            ]
        );

        let outer = found
            .iter()
            .find(|import| match &import.target {
                ImportTarget::ArtifactCandidates(paths) => {
                    paths.contains(&"crates/c/src/a.rs".to_string())
                        && !paths.contains(&"crates/c/src/a/b.rs".to_string())
                }
                ImportTarget::RustCrate { .. } | ImportTarget::Package(_) => false,
            })
            .expect("the outer a branch is extracted");
        assert_eq!(outer.bindings[0].imported, "E");
    }

    #[test]
    fn a_multiline_grouped_use_is_one_statement() {
        let found = extract(
            "crates/c/src/facade/query.rs",
            "use crate::{\n    embed, ingest,\n    MindLeak, Result,\n};\n",
        );
        let list = candidates(&found, "crate::{");
        assert!(
            list.contains(&"crates/c/src/lib.rs".to_string()),
            "`use crate::{{..}}` imports from the crate root; got {list:?}"
        );
    }

    #[test]
    fn another_crate_stays_unresolved_until_its_manifest_proves_a_root() {
        let found = extract(
            "crates/lodestar-core/src/lib.rs",
            "use mindleak_storage::resolve_database;\n",
        );
        assert_eq!(
            found.first().map(|import| import.target.clone()),
            Some(ImportTarget::RustCrate {
                name: "mindleak_storage".to_string(),
                segments: vec!["resolve_database".to_string()],
            })
        );
    }

    #[test]
    fn the_toolchain_is_not_a_workspace_edge() {
        let found = extract(
            "crates/c/src/lib.rs",
            "use std::collections::HashMap;\nuse core::fmt;\n",
        );
        assert!(
            found.is_empty(),
            "std/core are not files here; got {found:?}"
        );
    }

    #[test]
    fn a_use_inside_a_comment_or_string_is_not_an_import() {
        // Regression: doc comments in this repository are full of prose like
        // "use `check_overlap`", and a block comment can hold a whole
        // statement. Matching those would attach edges a file never declared.
        let found = extract(
            "crates/c/src/lib.rs",
            "// use crate::fake::Thing;\n/* use crate::alsofake::Thing; */\nlet s = \"use crate::stringfake::Thing;\";\nuse crate::real::Thing;\n",
        );
        assert_eq!(found.len(), 1, "only the real use counts; got {found:?}");
        assert!(found[0].specifier.contains("crate::real"));
    }

    #[test]
    fn a_file_outside_src_still_resolves_its_own_neighbours() {
        let found = extract("build/helper.rs", "mod inner;\n");
        assert_eq!(
            candidates(&found, "mod inner"),
            vec![
                "build/helper/inner.rs".to_string(),
                "build/helper/inner/mod.rs".to_string(),
            ]
        );
    }
}
